"""Commerce pages share the existing site header, typography, and footer."""
from html import escape
def address_fields(prefix='', billing=False):
    fields=[('name','Full name','name','text'),('email','Email address','email','email'),('phone','Phone (optional)','tel','tel'),('street1','Street address','address-line1','text'),('street2','Apartment, suite, etc. (optional)','address-line2','text'),('city','City','address-level2','text'),('state','State','address-level1','text'),('zip','ZIP code','postal-code','text')]
    html=f'<label class="field">Country<select name="{prefix}country" autocomplete="{"billing" if billing else "shipping"} country" data-billing-countries required><option value="US">United States</option></select></label>'
    if not billing:
        html='<input type="hidden" name="country" value="US"><p class="field">Country<span>United States</span></p>'
    for key,label,autocomplete,type_ in fields:
        required=' required' if key in ['name','email','street1','city'] or (not billing and key in ['state','zip']) else ''
        html+=f'<label class="field">{label}<input name="{prefix}{key}" type="{type_}" maxlength="{254 if key=="email" else 100}" autocomplete="{"billing" if billing else "shipping"} {autocomplete}"{required}></label>'
    return html

def render_commerce_pages(page, store):
    page('cart.html','Your bag','Your Blue Koi shopping bag.', '''<section class="page-top wrap"><p class="eyebrow">A little care, on its way</p><h1>Your bag.</h1><p class="lead">Handmade in Virginia. Packed with care.</p></section><section class="wrap commerce-layout"><div id="cart-items" aria-live="polite"><p>Loading your bag…</p></div><aside class="order-summary"><h2>Order summary</h2><div id="cart-summary"></div><a class="button full" href="checkout.html" id="checkout-link">Continue to checkout</a><p class="small muted">Shipping choices and tax are calculated at checkout. Orders process in 1–3 days.</p><p class="small"><a href="shipping-returns.html">Shipping &amp; returns</a></p></aside></section>''')
    page('checkout.html','Checkout','Secure checkout for Blue Koi Botanicals.', f'''<section class="page-top wrap"><p class="eyebrow">Almost yours</p><h1>Checkout.</h1><p class="lead">Choose your delivery service, then pay securely by card.</p><div id="shipping-promotion" class="notice" hidden><strong>Free shipping for the first 50 customers on orders over $25.</strong><p>Use code <b>FREESHIP25</b> at checkout.</p><small class="promotion-terms">Applies to the lowest-priced available shipping service.</small><button type="button" class="button secondary" id="use-shipping-code">Use FREESHIP25</button></div><div id="checkout-mode" class="notice" role="status"></div></section><section class="wrap commerce-layout"><div><form method="post" id="address-form"><h2 class="form-title">1. Delivery address</h2><div class="form-grid">{address_fields()}</div><p class="small muted">We ship only to the 50 U.S. states and Washington, D.C. CBD products cannot ship to Colorado, Idaho, or Wyoming.</p><label class="field discount-entry">Discount code (optional)<input id="discount-code" name="discount_code" maxlength="32" autocomplete="off" autocapitalize="characters" placeholder="Enter code"></label><p id="discount-status" class="small muted" role="status"></p><button class="button" type="submit" id="get-rates" disabled>Get shipping options</button></form><section id="shipping-step" hidden><h2 class="form-title">2. Shipping method</h2><p class="small muted">Carrier estimates are in addition to our 1–3 day processing time.</p><fieldset id="shipping-rates"><legend class="sr-only">Choose your shipping service</legend></fieldset><p id="parcel-note" class="small muted"></p></section><section id="payment-step" hidden><h2 class="form-title">3. Payment</h2><label class="checkbox"><input type="checkbox" id="billing-same" checked> Billing address matches delivery address</label><form method="post" id="billing-form" hidden><div class="form-grid">{address_fields('billing_',True)}</div></form><div id="card-container"></div><p class="small muted">Your card is processed securely by Square. Blue Koi does not receive your card number.</p><button class="button full" id="pay-button" type="button" disabled>Pay securely</button><p class="small">By placing an order, you agree to our <a href="shipping-returns.html">shipping and return policy</a>. Read our <a href="privacy.html">privacy notice</a>.</p></section><div id="checkout-error" class="notice error" role="alert" hidden></div></div><aside class="order-summary"><h2>Your order</h2><div id="checkout-items"></div><div id="checkout-totals"></div><a class="text-link" href="cart.html">Edit your bag</a><p class="small muted">Need a hand? <a href="mailto:blue.koi.botanicals@gmail.com">Email us</a>.</p></aside></section>''')
    page('order.html','Your order','Your Blue Koi order status.', '''<section class="page-top wrap"><p class="eyebrow">Blue Koi Botanicals</p><h1 id="order-title">Checking your order.</h1><p class="lead" id="order-message" role="status">Please keep this page open while we confirm payment.</p></section><section class="wrap narrow section-bottom"><div id="order-details"></div><p class="small">Questions? Email <a href="mailto:blue.koi.botanicals@gmail.com">blue.koi.botanicals@gmail.com</a> with your order number.</p><div class="actions"><a class="button secondary" href="products.html">Back to the collection</a></div></section>''')
    page('review.html','Share your experience','Leave a verified purchase review for your Blue Koi products.', '''<section class="page-top wrap narrow"><p class="eyebrow">From your own experience</p><h1>How did it feel?</h1><p class="lead">Your honest feedback helps other customers choose. Reviews are linked to a purchase; your email and order number stay private.</p></section><section class="wrap narrow section-bottom"><div id="review-invitation" role="status">Open the private review link from your email to get started.</div><form method="post" id="review-form" hidden><label class="field">Your product<select name="slug" required></select></label><label class="field">Your rating<select name="rating" required><option value="">Choose a rating</option><option value="5">5 — Loved it</option><option value="4">4 — Liked it</option><option value="3">3 — It was okay</option><option value="2">2 — Could be better</option><option value="1">1 — Disappointed</option></select></label><label class="field">Public display name<input name="author" maxlength="60" required placeholder="First name or initials"></label><label class="field">Your review<textarea name="body" rows="6" minlength="10" maxlength="2000" required></textarea></label><p class="small muted">Please avoid personal contact information. Reviews are checked for spam and inappropriate content before publication; positive and negative reviews are welcome.</p><button class="button" type="submit">Submit your review</button><p id="review-result" role="status"></p></form></section>''')
    page('admin.html','Store management','Blue Koi store management.', '''<section class="page-top wrap"><p class="eyebrow">For Gwyn</p><h1>Store management.</h1><p class="lead">Review submissions and website orders. Manage payments, refunds, and shipment fulfillment in Square.</p></section><section class="wrap section-bottom"><form method="post" id="admin-login" class="narrow"><label class="field">Store access key<input name="token" type="password" autocomplete="off" required minlength="32"></label><button class="button">Open management</button></form><p id="admin-message" role="status"></p><div id="admin-content" hidden><div class="actions"><button class="button secondary" id="admin-refresh">Refresh</button><button class="button secondary" id="admin-logout">Sign out</button><a class="text-link" href="https://squareup.com/dashboard/orders" target="_blank" rel="noopener noreferrer">Open Square</a><a class="text-link" href="https://app.goshippo.com" target="_blank" rel="noopener noreferrer">Open Shippo</a></div><div id="admin-status" class="notice"></div><h2 class="form-title">Discount codes</h2><p class="small muted">Codes apply only to merchandise before sales tax, except free-shipping codes. Free-shipping codes cover the lowest-priced available service.</p><form id="discount-code-form" class="admin-card"><div class="form-grid"><label class="field">Code<input name="code" maxlength="32" required placeholder="SAVE10" autocapitalize="characters"></label><label class="field">Type<select name="kind"><option value="percent">Percent off merchandise</option><option value="fixed">Dollar amount off merchandise</option><option value="free_shipping">Free lowest-cost shipping</option></select></label><label class="field">Amount<input name="amount" type="number" min="0" step="0.01" required placeholder="10"></label><label class="field">Minimum merchandise subtotal (optional)<input name="minimum" type="number" min="0" step="0.01" value="0"></label></div><p class="small muted">For a free-shipping code over $25, choose “Free lowest-cost shipping,” use amount 0, and enter 25.01 as the minimum.</p><button class="button">Create code</button></form><div id="admin-discounts"></div><h2 class="form-title">Invite past customers</h2><p class="small muted">Invite customers whose purchases you have verified, including market, Square POS, and Etsy sales. Select only the products they purchased. Invite customers regardless of whether you expect positive or negative feedback.</p><form id="past-invitation-form" class="admin-card"><div class="form-grid"><label class="field">Customer name<input name="customer_name" required maxlength="80" autocomplete="off"></label><label class="field">Customer email<input name="email" type="email" required maxlength="254" autocomplete="off"></label><label class="field">Purchase source<select name="source"><option value="square">Square / POS</option><option value="market">Market / cash</option><option value="etsy">Etsy</option><option value="other">Other prior purchase</option></select></label><label class="field">Receipt or sale reference<input name="purchase_reference" required maxlength="120" placeholder="Receipt number or unique market sale reference"></label><label class="field">Purchase date<input name="purchased_on" type="date" required></label></div><fieldset id="past-invitation-products"><legend>Purchased products</legend><p>Loading products…</p></fieldset><label class="checkbox"><input type="checkbox" name="purchase_verified" required>I checked this purchase and confirmed these products were purchased.</label><p class="small muted">This sends one private review invitation to the email above. No purchase or payment is created. Links last 90 days; submitted reviews wait for moderation.</p><button class="button" type="submit">Send review invitation</button><p id="past-invitation-message" role="status"></p></form><div id="past-invitation-list"></div><h2 class="form-title">Customer reviews</h2><div id="admin-reviews"></div><h2 class="form-title">Website orders</h2><p class="small muted">Buy labels in Shippo using the parcel details below. Mark shipments fulfilled in Square to schedule review invitations. Purchasing labels is not automated.</p><div id="admin-orders"></div></div></section>''')
    page('shipping-returns.html','Shipping & returns','Processing times, shipping options, and returns for Blue Koi Botanicals.', '''<section class="page-top wrap narrow"><p class="eyebrow">Good to know</p><h1>Shipping &amp; returns.</h1></section><article class="wrap narrow policy section-bottom"><h2>Made here. Sent with care.</h2><p>Orders ship from Charlottesville, Virginia. Please allow 1–3 days for processing before your order is handed to the carrier. Transit time depends on the shipping service you choose; delivery estimates are not guarantees.</p><h2>Shipping options</h2><p>We ship to the 50 U.S. states and Washington, D.C. We do not offer international shipping. CBD products cannot ship to Colorado, Idaho, or Wyoming; orders containing CBD must use an eligible destination or have all CBD items removed. Non-CBD products can ship to those states. If your address does not return a rate, please contact us.</p><p>Enter your delivery address at checkout to see available services and current shipping prices. We combine items into one parcel, using our larger box for multi-item orders. Shipping rates include product weight and one box. Contact us about unusually large or bulky orders.</p><h2>Sales tax</h2><p>Applicable sales tax is shown before you pay. A 5.3% sales tax is applied to the merchandise subtotal on every order, regardless of delivery destination. Separately stated shipping is not taxed.</p><h2>Defective items</h2><p>Refunds are available for defective items. Please email <a href="mailto:blue.koi.botanicals@gmail.com">blue.koi.botanicals@gmail.com</a> with your order number and a description of the defect. A photo is helpful. Gwyn will help arrange the refund and let you know whether the item needs to be returned.</p><h2>Questions about an order?</h2><p><a href="contact.html">Contact us</a> for help with delivery, an item, or a refund.</p></article>''')
    page('privacy.html','Privacy','How Blue Koi Botanicals uses information for orders and reviews.', '''<section class="page-top wrap narrow"><p class="eyebrow">Your information</p><h1>Privacy.</h1></section><article class="wrap narrow policy section-bottom"><h2>Orders and delivery</h2><p>We use your name, contact details, delivery address, billing address, and order information to process purchases, arrange shipping, provide customer service, and keep business records. Square processes card payments; we do not receive or store your full card number. Shippo and carriers receive the information needed for shipping. Cloudflare hosts the store and its order database, and Resend delivers order and review emails.</p><h2>Your bag and session</h2><p>Your browser stores the items in your shopping bag. An essential session cookie connects your checkout to your order so that other visitors cannot open your order details. These features are needed to operate the shop.</p><h2>Reviews</h2><p>After a fulfilled order, we may email a private link inviting you to review the products you purchased. We may also invite past customers after verifying their purchase records, using their contact details, purchase reference, and purchased products. Leaving a review is optional. Your chosen display name, rating, review text, and date appear publicly if the review is published. Your email and order number are not published.</p><h2>Records and questions</h2><p>We keep transaction records for business and accounting purposes and restrict store management access. Contact <a href="mailto:blue.koi.botanicals@gmail.com">blue.koi.botanicals@gmail.com</a> to ask about your information, request a correction, or ask to have a review removed.</p></article>''')
